  report_name: extractText(/<h4[^>]*>\s*Reports\s*:\s*([\s\S]*?)<\/h4>/i),
  date_range: extractText(/Reports Date Range\s*:\s*([\s\S]*?)<\/h4>/i),
  printed_at: extractText(/Printing Date\s*\/\s*Time\s*:\s*([\s\S]*?)<\/h4>/i),
  branch: extractText(/<h4[^>]*>\s*Branch\s*:\s*([\s\S]*?)<\/h4>/i),
  cash_receipt: extractAmount(html, 'Cash Account(Reciept)'),
  card_receipt: extractAmount(html, 'Credit Card(Reciept)'),
  grand_total_receipt: extractAmount(html, 'Grand Total Receipt'),
  total_income: extractAmount(html, 'Total Income'),
  cash_in_hand: extractAmount(html, 'Cash in Hand'),
  cash_received_total: cash.received_total,
  cash_expense_total: cash.expense_total,
  cash_balance: cash.balance,
  credit_card_received_total: cardExp.received_total,
  credit_card_expense_total: cardExp.expense_total,
  credit_card_balance: cardExp.balance,
  expense_total: round(expense_sections.reduce((sum, s) => sum + Number(s.expense_total || 0), 0)),
  balance: round(expense_sections.reduce((sum, s) => sum + Number(s.balance || 0), 0)),
  total_invoice: extractAmount(html, 'Total Invoice'),
